  FORM['ledger-adjust'] = (d, f) => { const m = S().members.find(x => x.id === d.q || x.email === d.q || x.name === d.q); if (!m) return U.toast('Pick a member from the list', 'err'); f.dataset.id = m.id; FORM.adjust(d, f); U.close(); };

